input.new_string:
const FIRST_INSURANCE_SURCHARGE = 0.1;

const quote = (items: Item[]): QuoteResult => {
  const base = items.length * 100;
  return { premium: base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => quote((step as QuoteStep).items)),
