export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const policyBaseOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

// Keep this as `base + base * RATE`. The algebraically equivalent
// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
// upward float error rather than absorbing it.
const quote = (items: Item[]): QuoteResult => {
  const policyBase = policyBaseOf(items);

  return {
    premium: Math.ceil(
      policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
    ),
  };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => quote((step as QuoteStep).items)),
});

