const BLOCK_SIZE = 3;

const BLOCK_BASE_PREMIUM = 60;

const countsByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
};

const basePremiumFor = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBaseOf = (items: Item[]): number => {
  let total = 0;

  for (const [type, count] of countsByType(items)) {
    total += basePremiumFor(type, count);
  }

  return total;
};

