import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single items -------------------------------------
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("sword → base premium 100 G", () => {
    // 100 G base + 10 G first insurance + 5 G fee = 115 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("amulet → base premium 60 G", () => {
    // 60 G base + 6 G first insurance + 5 G fee = 71 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("staff → base premium 80 G", () => {
    // 80 G base + 8 G first insurance + 5 G fee = 93 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("potion → base premium 40 G", () => {
    // 40 G base + 4 G first insurance + 5 G fee = 49 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });
  it("single rune → base premium 25 G", () => {
    // 25 G base + 2.5 G first insurance + 5 G fee = 32.5 G → 33 G (rounded up)
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("single moonstone → base premium 25 G", () => {
    // 25 G base + 2.5 G first insurance + 5 G fee = 32.5 G → 33 G (rounded up)
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });

  // --- Component blocks --------------------------------------------------
  it("2 runes → 50 G base premium", () => {
    // 50 G base + 5 G first insurance + 5 G fee = 60 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies)", () => {
    // block of 3 = 60 G base + 6 G first insurance + 5 G fee = 71 G
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ------------------------------------------
  it.todo("cursed sword adds 50 % of its base premium as risk surcharge");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");

  // --- Policy-wide modifiers ---------------------------------------------
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first quote carries a 10 % initial assessment surcharge");
  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
  it.todo("first insurance surcharge still applies on a follow-up contract");

  // --- Modifier scope on multi-item policies ------------------------------
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
  );

  // --- Rounding ------------------------------------------------------------
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples -------------------------------------------------
  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");

  // --- Claim: standard reimbursement ----------------------------------------
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");

  // --- Claim: special clauses ------------------------------------------------
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event -------------------------------------
  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G");

  // --- Claim: cap ---------------------------------------------------------------
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
  it.todo("sword, two successive claims of 1500 G → first payout 1400 G, remaining cap 600 G");
  it.todo("sword, second claim of 1500 G → payout 600 G, remaining cap 0 G");

  // --- Claim: multiple items of the same type -------------------------------------
  it.todo("two swords insured, two sword damages → each damage gets its own deductible");
  it.todo("more damage entries of a type than insured → claim rejected (error)");

  // --- Errors ------------------------------------------------------------------------
  it.todo("quote with an unknown item type (broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet, only sword insured) → error");
  it.todo("claim referencing a damage entry with an unknown item type → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- CLI ---------------------------------------------------------------------------
  it.todo("CLI reads a scenario from stdin and writes results JSON to stdout");
  it.todo("CLI exits with a non-zero status and writes to stderr on an invalid scenario");
});

