const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

const policyModifierRate = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE - (isLoyal(customer) ? LOYALTY_DISCOUNT : 0);

const quote = (items: Item[], customer: Customer): QuoteResult => {
  const policyBase = policyBasePremium(items);

  return {
    premium: Math.ceil(
      policyBase +
        itemSurcharges(items) +
        policyBase * policyModifierRate(customer) +
        PROCESSING_FEE,
    ),
  };
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") return quote(step.items, customer);

  throw new Error(`Unsupported step: ${step.op}`);
