  // premium with modifiers is 165 G, but the cap is based on the unmodified
  // 1000 G insurance value: 2 × 1000 = 2000 G
  const result = runScenario({
    customer: { yearsWithMHPCO: 0 },
    steps: [
      { op: "quote", items: [{ type: "sword", cursed: true }] },
      {
        op: "claim",
